// Isolated design prototype. All values and evidence below are synthetic.
const $ = (selector) => document.querySelector(selector);
const names = {overview:'总览', sessions:'会话', trust:'外传审计'};
let page = 'overview';
let period = 'today';
let harnessFilter = '全部';
let query = '';
let selectedSession = 0;
let evidence = 'archive';
let monitoring = true;
const sessions = [
  ['Codex','Runtime 事件管道重构','gpt-5.6','14:32','2.8M','96.8%'],
  ['Claude Code','工作台交互细节调整','claude-sonnet','14:18','1.4M','98.2%'],
  ['ZCode','数据源适配器测试','glm','13:46','842K','94.1%'],
  ['Codex','会话查询回归测试','gpt-5.6','13:21','3.2M','97.4%'],
  ['MiniMax Code','整理接口类型定义','MiniMax','12:54','620K','91.3%'],
  ['Claude Code','费用计算边界检查','claude-sonnet','12:06','4.1M','98.9%'],
  ['Codex','修复同步状态反馈','gpt-5.6','11:42','1.7M','96.2%'],
  ['Claude Code','审核本地投影查询','claude-sonnet','10:35','2.2M','97.6%'],
];
const bars=[18,12,9,7,5,8,18,34,58,40,67,50,76,53,86,68,60,79,48,65,91,73,82,63];
function overview(){
 const today=period==='today';
 return `<div class="section-top"><div><h1>${today?'今天的工作台':'本月的工作台'}</h1><p class="subline">2026 年 9 月 ${today?'24 日 · 星期四':'· 月度汇总'}</p></div><div class="segmented"><button data-period="today" class="${today?'active':''}">今天</button><button data-period="month" class="${!today?'active':''}">本月</button></div></div>
 <div class="metrics"><div class="metric"><small>Token 消耗</small><strong>${today?'146.0M':'1.28B'}</strong><p>缓存命中 <em>98.55%</em></p></div><div class="metric"><small>${today?'已知成本 · 含订阅日均摊':'已知支出'}</small><strong>¥${today?'5.40':'182.55'}</strong><p>另有 US$${today?'1.33':'40.00'} · 币种分列</p></div><div class="metric"><small>模型标价等价成本</small><strong>¥${today?'286.20':'2,480.00'}</strong><p>按模型公开单价估算，非实付</p></div></div>
 <section class="section"><div class="section-heading"><h2>消耗趋势</h2><span class="muted" style="font-size:11px">${today?'按小时 · 含缓存读写':'按日 · 含缓存读写'}</span></div><div class="chart" role="img" aria-label="模拟消耗趋势，午后消耗较高">${bars.map((h,i)=>`<div class="bar" style="height:${today?h:bars[23-i]}%" title="${today?i+' 时':(i+1)+' 日'} · 模拟用量"></div>`).join('')}</div><div class="chart-labels">${(today?['00:00','06:00','12:00','18:00','23:00']:['9 月 1 日','7 日','14 日','21 日','24 日']).map(x=>`<span>${x}</span>`).join('')}</div></section>
 <section class="section"><div class="section-heading"><h2>执行环境用量</h2><button class="text-button" data-go="sessions">查看会话 ›</button></div><div class="table-wrap"><table><thead><tr><th>执行环境</th><th class="num">会话</th><th class="num">Tokens</th><th class="num">缓存命中</th></tr></thead><tbody>${[['Claude Code','64','88.2M','98.9%'],['Codex','42','39.4M','98.1%'],['ZCode','17','16.2M','97.2%'],['MiniMax Code','5','2.2M','91.3%']].filter(r=>r[0].toLowerCase().includes(query.toLowerCase())).map(r=>`<tr><td class="harness-name">${r[0]}</td><td class="num">${r[1]}</td><td class="num">${r[2]}</td><td class="num"><span class="tiny-bar"><i style="width:${r[3]}"></i></span>${r[3]}</td></tr>`).join('')}</tbody></table></div></section>
 <section class="section"><div class="section-heading"><h2>需要关注 <span class="muted">· 2</span></h2><button class="text-button" data-go="trust">全部证据 ›</button></div>${riskRows()}</section>`;
}
function riskRows(){return `<button class="list-row" data-evidence="archive"><span class="risk-icon">◇</span><span class="body"><strong>发现包含 Git 历史的归档线索</strong><p>ZCode · 本地清单与客户端接受状态 · 14:26</p></span><span class="pill warning">待核查</span></button><button class="list-row" data-evidence="coverage"><span class="risk-icon">!</span><span class="body"><strong>MiniMax Code 历史审计覆盖不完整</strong><p>尚无可用历史解析器，不代表没有风险</p></span><span class="pill neutral">覆盖缺口</span></button>`;}
function sessionPage(){const rows=sessions.map((r,i)=>({r,i})).filter(({r})=>(harnessFilter==='全部'||r[0]===harnessFilter)&&r.join(' ').toLowerCase().includes(query.toLowerCase()));return `<div class="section-top"><div><h1>最近会话</h1><p class="subline">今天 · 2026 年 9 月 24 日</p></div><span class="pill neutral">模拟会话</span></div><div class="filterbar"><div class="segmented">${['全部','Codex','Claude Code'].map(x=>`<button data-filter="${x}" class="${harnessFilter===x?'active':''}">${x}</button>`).join('')}</div><span class="muted">${rows.length} 个结果</span></div><div class="table-wrap"><table><thead><tr><th>会话 / 执行环境</th><th>时间</th><th class="num">Tokens</th><th class="num">缓存</th></tr></thead><tbody>${rows.map(({r,i})=>`<tr class="selectable ${i===selectedSession?'selected':''}" data-session="${i}" tabindex="0" aria-label="查看${r[1]}"><td><span class="harness-name">${r[1]}</span><div class="subline">${r[0]}</div></td><td class="muted">${r[3]}</td><td class="num">${r[4]}</td><td class="num">${r[5]}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">没有匹配的模拟会话</div>':''}</div><p class="note">点击会话在右侧查看详情。标题为原型虚构内容，不读取真实日志。</p>`;}
function trustPage(){return `<div class="section-top"><div><h1>外传审计</h1><p class="subline">先看证据，再判断风险</p></div><button class="button" id="audit">重新审计</button></div><div class="audit-summary"><span class="dot ${monitoring?'':'amber'}"></span><span>${monitoring?'后台监测已开启':'后台监测已暂停'}</span><span class="muted">· 3 / 4 执行环境具备历史审计能力</span><button class="text-button" id="monitor">${monitoring?'暂停':'开启'}</button></div><div class="section-heading"><h2>待核查证据</h2><span class="muted" style="font-size:11px">2 项</span></div><div class="evidence-group">${riskRows()}</div><p class="note">本地归档与接受状态不能单独证明文件已上传，更不能证明未经授权使用。</p><section class="section"><div class="section-heading"><h2>审计覆盖</h2></div><div class="table-wrap"><table><thead><tr><th>执行环境</th><th>历史证据</th><th>进程监测</th></tr></thead><tbody>${['Claude Code','Codex','ZCode','MiniMax Code'].map((h,i)=>`<tr><td class="harness-name">${h}</td><td><span class="pill ${i===3?'warning':'neutral'}">${i===3?'覆盖不完整':i===2?'3 条线索':'未发现线索'}</span></td><td>${monitoring?'已开启':'已暂停'}</td></tr>`).join('')}</tbody></table></div></section>`;}
function inspector(){if(page==='sessions'){const r=sessions[selectedSession];return `<div class="inspector-header">会话检查器<span>MOCK</span></div><span class="pill neutral">${r[0]}</span><h2>${r[1]}</h2><p>会话摘要与用量，均为模拟数据。</p><dl class="properties"><dt>开始时间</dt><dd>今天 ${r[3]}</dd><dt>模型</dt><dd>${r[2]}</dd><dt>Token 消耗</dt><dd>${r[4]}</dd><dt>缓存命中</dt><dd>${r[5]}</dd><dt>计费归属</dt><dd>尚未确认</dd></dl><hr><h3>活动摘要</h3><div class="timeline" style="margin-top:18px"><div><small>${r[3]}</small><strong>开始任务</strong></div><div><small>+ 02:14</small><strong>读取项目结构 · 12 次调用</strong></div><div><small>+ 06:32</small><strong>运行测试 · 全部通过</strong></div></div><p class="note">计费归属待确认。模型等价费用不作为实际支出。</p>`;}
 if(evidence==='coverage')return `<div class="inspector-header">覆盖详情<span>MOCK</span></div><span class="pill warning">证据不足</span><h2>MiniMax Code</h2><p>检测到执行环境，但当前原型场景没有可用的历史解析能力。</p><dl class="properties"><dt>进程监测</dt><dd>${monitoring?'已开启':'已暂停'}</dd><dt>历史审计</dt><dd>未覆盖</dd><dt>风险结论</dt><dd>无法判断</dd></dl><hr><h3>下一步</h3><p>补充执行环境 Profile 与历史证据解析，再执行本地审计。不能把“没有结果”当成“没有风险”。</p>`;
 return `<div class="inspector-header">证据检查器<span>MOCK</span></div><span class="pill warning">需要核查</span><h2>Git 历史归档线索</h2><p>ZCode 的模拟清单包含 Git 对象，同时存在客户端记录的接受状态。</p><dl class="properties"><dt>执行环境</dt><dd>ZCode</dd><dt>发现时间</dt><dd>今天 14:26:08</dd><dt>归档大小</dt><dd>313.2 MB</dd><dt>Git 内容占比</dt><dd>86.6%</dd><dt>证据强度</dt><dd>中 · 客户端记录</dd><dt>网络传输</dt><dd>尚未证实</dd></dl><hr><h3>证据时间线</h3><div class="timeline" style="margin-top:18px"><div><small>14:24:32 · 本地文件</small><strong>发现归档清单</strong><code>~/MockAgent/checkpoints/demo/manifest.json</code></div><div><small>14:25:01 · 客户端状态</small><strong>存在 accepted 字段</strong><code>~/MockAgent/checkpoints/demo/state.json</code></div><div><small>14:26:08 · 本次审计</small><strong>关联为同一组待核查线索</strong></div></div><div class="actions"><button class="button" id="evidence-detail">查看证据字段</button><button class="button" id="acknowledge">标记已阅</button></div><div id="evidence-fields" hidden><p class="note">模拟字段</p><code style="font-size:11px;line-height:1.8">kind: baseline<br>includes_git_objects: true<br>accepted: true<br>upload_verified: unknown</code></div><p class="note">路径及记录均为虚构。接受状态不等于已验证上传；不据此指控“偷代码”。</p>`;}
function render(){ $('#content').innerHTML=page==='overview'?overview():page==='sessions'?sessionPage():trustPage();$('#inspector').innerHTML=inspector();$('#page-title').textContent=names[page];document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('selected',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');}); }
function navigate(next){page=next;query='';$('#search').value='';render();$('#content').scrollTop=0;}
function feedback(message){$('#status').textContent=message;}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-session]');if(!b)return;if(b.dataset.page)navigate(b.dataset.page);if(b.dataset.go)navigate(b.dataset.go);if(b.dataset.period){period=b.dataset.period;render();}if(b.dataset.filter){harnessFilter=b.dataset.filter;render();}if(b.dataset.session){selectedSession=Number(b.dataset.session);$('#window').classList.remove('hide-inspector');$('#window').classList.add('show-inspector');render();}if(b.dataset.evidence){evidence=b.dataset.evidence;$('#window').classList.remove('hide-inspector');$('#window').classList.add('show-inspector');render();}if(b.id==='sidebar-toggle')$('#window').classList.toggle('hide-sidebar');if(b.id==='inspector-toggle'){if(innerWidth<=850)$('#window').classList.toggle('show-inspector');else $('#window').classList.toggle('hide-inspector');}if(b.id==='appearance')document.body.classList.toggle('dark');if(b.id==='monitor'){monitoring=!monitoring;render();feedback(`模拟监测已${monitoring?'开启':'暂停'}，未改变真实设置`);}if(b.id==='evidence-detail')$('#evidence-fields').hidden=!$('#evidence-fields').hidden;if(b.id==='acknowledge'){b.textContent='已阅';b.disabled=true;feedback('已标记为已阅 · 仅本次原型展示，未修改真实证据');}if(b.id==='refresh'||b.id==='audit'){b.disabled=true;feedback('正在更新模拟数据…');setTimeout(()=>{b.disabled=false;feedback('模拟更新完成 · 刚刚 · 未读取本机数据');},700);}});
$('#search').addEventListener('input',e=>{query=e.target.value;render();});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='f'){e.preventDefault();$('#search').focus();}if(e.key==='Escape')$('#window').classList.remove('show-inspector');if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-session]')){e.preventDefault();e.target.click();}});
render();
